export const leafSize = (v: Value, measure: Measure): number | undefined => {
  switch (v.kind as string) {
    case "nothing": return 8;
    case "boolean": return 8;
    case "number": return 16;
    case "quantity": return 24;
    case "text": return 16 + Math.ceil((1 * measure(5, v)) / 1);
    case "bytes": return 16 + Math.ceil((1 * measure(6, v)) / 1);
    case "instant": return 16;
    case "civil date": return 16;
    case "pattern": return 16 + Math.ceil((8 * measure(12, v)) / 1);
    case "object": return 16;
    case "deadline": return 40;
    case "pending call": return 48;
  }
};
